/// Returns true if `sub` matches `main` starting exactly at index `start`.
/// If `start + sub.len()` exceeds `main.len()`, returns false.
fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Quick check to avoid out‐of‐bounds access
    if start + sub.len() > main.len() {
        return false;
    }
    // Compare element‐wise
    for i in 0..sub.len() {
        if main[start + i] != sub[i] {
            return false;
        }
    }
    true
}

/// Returns true if `sub` appears as a contiguous subarray of `main`.
/// The empty `sub` always qualifies (returns true),
/// and if `sub.len() > main.len()`, returns false.
fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // If sub is longer, it can't be a subarray
    if sub.len() > main.len() {
        return false;
    }
    // Try every possible starting position
    let max_start = main.len() - sub.len();
    for start in 0..=max_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}

